import{_ as s,o as r,c as t,j as e,a as i,a5 as o}from"./chunks/framework.DrDMl0tG.js";const l="/assets/rayrai_fluid_waves.BAQAfmtq.mp4",f=JSON.parse('{"title":"Rayrai Example: Floating on Waves","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_fluid_waves.md","filePath":"sections/examples/rayrai/rayrai_fluid_waves.md"}'),d={name:"sections/examples/rayrai/rayrai_fluid_waves.md"};function n(h,a,c,p,m,u){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"rayrai-example-floating-on-waves",tabindex:"-1"},[i("Rayrai Example: Floating on Waves "),e("a",{class:"header-anchor",href:"#rayrai-example-floating-on-waves","aria-label":'Permalink to "Rayrai Example: Floating on Waves"'},"​")],-1),e("p",null,[e("video",{class:"doc-video",src:l,loop:"",muted:"",playsinline:"",preload:"metadata","aria-label":"Wooden crates, a raft, blue barrels and beach balls ride the swell of the sea"})],-1),o('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Wooden crates, a raft, barrels and beach balls ride the swell of the sea. The sea of the RaiSim world (<a href="./../../Fluids.html">Fluids</a>) samples the same Gerstner waves that rayrai draws, at the physics time, through <code>FluidVolume::sampler</code>. The water holds every body up where the drawn surface is: they heave on the crests and roll and pitch with the slope of the waves. The sampler also returns how fast the surface rises and falls, so the bodies move with the water instead of only being pushed by it. The example renders in process with <code>raisin::RayraiWindow</code> and does not need <code>rayrai_tcp_viewer</code>.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_fluid_waves</code> (C++20).</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_fluid_waves</span></span></code></pre></div><p>On Windows, run <code>rayrai_fluid_waves.exe</code> instead. The example takes no arguments. Drag to look around and use WASD and Space to move.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>The sea is rayrai&#39;s ocean with twelve Gerstner waves from 1.2 m to 16 m long (<code>raisin::generateGerstnerWaves()</code>). <code>raisin::sampleWaterSurface()</code> evaluates the same waves on the CPU, so the physics does not wait for the renderer.</li><li>The crates are 600 kg/m³, the raft 450 kg/m³, the barrels 500 kg/m³. The beach balls weigh 0.4 kg for 0.11 m³, so they ride on top of the waves and are blown about by the slopes.</li><li>The sea is sea water under air (<code>World::setAmbientFluid()</code>), and the bodies make waves of their own as they bob, which damps them.</li><li>The scene lives in <code>src/rayrai/physics/fluid_waves_scene.hpp</code>.</li></ul>',9)])])}const w=s(d,[["render",n]]);export{f as __pageData,w as default};
